// Some portions generated by Co-Pilot
"use client";

import { Fragment, useMemo, useState, type ComponentType } from "react";
import { Link } from "@/i18n/navigation";
import Image from "next/image";
import { useTranslations, useLocale } from "next-intl";
import { sendDownloadEvent } from "@/utils/gtag";
import type { BinaryAssetView } from "@/types/temurin";
import { getSizeMB, getExtension } from "@/utils/temurin";
import { FaWindows, FaApple } from "react-icons/fa";
import { FcLinux } from "react-icons/fc";
import { SiAlpinelinux } from "react-icons/si";
import { AixIcon, SolarisIcon } from "@/components/Common/Icon";
import { BsCopy } from "react-icons/bs";
import { FiDownload } from "react-icons/fi";
import { MdVerifiedUser } from "react-icons/md";
import { useAttestations } from "@/hooks/useAttestations";
import { IoWarningOutline } from "react-icons/io5";

interface ReleaseResultsProps {
  releases: BinaryAssetView[];
  isLoading: boolean;
  openModalWithChecksum: (checksum: string) => void;
}

interface DownloadRowProps {
  view: BinaryAssetView;
  artifact: NonNullable<NonNullable<BinaryAssetView["binary"]>["package"]>;
  os: string;
  arch: string;
  rowId: string;
  installer?: boolean;
  reproduced: boolean;
  openModalWithChecksum: (checksum: string) => void;
}

const osIcons: Record<string, ComponentType<{ size?: number }>> = {
  windows: FaWindows,
  mac: FaApple,
  "alpine-linux": SiAlpinelinux,
  linux: FcLinux,
  aix: AixIcon,
  solaris: SolarisIcon,
};
const osOrder = ["linux", "windows", "mac", "alpine-linux", "aix", "solaris"];
const isUnsupportedPlatform = (os: string, arch: string) =>
  os === "solaris" || (os === "windows" && arch === "x32");

const DownloadRow = ({
  view,
  artifact,
  os,
  arch,
  rowId,
  installer = false,
  reproduced,
  openModalWithChecksum,
}: DownloadRowProps) => {
  const t = useTranslations("Temurin.Releases.ReleaseResults");
  const tPage = useTranslations("TemurinReleases");
  const imageType = (view.binary?.image_type ?? "").toUpperCase();
  const extension =
    getExtension(artifact.name).toUpperCase() || (installer ? "INSTALLER" : "");
  const link = artifact.link;
  if (!link) return null;
  return (
    <div
      className="flex flex-wrap items-center justify-between gap-3 border-t border-white/10 py-4"
      data-testid={`binary-row-${rowId}`}
    >
      <div className="flex flex-wrap items-center gap-3">
        <Link
          href={{ pathname: "/download", query: { link, vendor: "Adoptium" } }}
          aria-label={`${tPage("download")} ${os} ${arch} ${imageType} ${extension}`}
          onClick={() =>
            sendDownloadEvent({
              link,
              os,
              arch,
              pkg_type: installer ? "installer" : imageType,
              version: view.release_name ?? "",
              vendor: "temurin",
            })
          }
          data-testid={`download-link-${rowId}`}
          className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-pink/30 bg-pink/10 px-4 py-2 text-sm font-medium text-[#ff91b7] transition-colors hover:bg-pink hover:text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink"
        >
          <FiDownload aria-hidden="true" />
          <span
            data-testid={`binary-info-${rowId}`}
          >{`${extension}, ${getSizeMB(artifact.size)} MB`}</span>
        </Link>
        <div className="flex items-center gap-2">
          <MdVerifiedUser
            size={20}
            className="text-[#96b8e4]"
            title={t("this-build-is-jck-certified")}
          />
          <Link
            href="/aqavit/"
            className="rounded focus-visible:outline-2 focus-visible:outline-pink"
          >
            <Image
              src="/images/icons/aqavit-icon.png"
              width={20}
              height={20}
              alt="AQAvit logo"
              title={t("this-build-is-aqavit-verified")}
            />
          </Link>
          {reproduced && (
            <Image
              src="/images/icons/reproduced-verified.svg"
              width={20}
              height={20}
              alt="Reproducibility Verified"
              title="This build is reproduced by a 3rd party"
            />
          )}
        </div>
      </div>
      <button
        type="button"
        disabled={!artifact.checksum}
        onClick={() => {
          if (artifact.checksum) openModalWithChecksum(artifact.checksum);
        }}
        data-testid={`checksum-link-${rowId}`}
        className="inline-flex min-h-11 items-center gap-2 rounded px-2 text-xs text-grey transition-colors hover:text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink disabled:cursor-not-allowed disabled:opacity-40"
      >
        <BsCopy aria-hidden="true" />
        <span>{t("checksum")}</span>
      </button>
    </div>
  );
};

const ReleaseResults = ({
  releases,
  isLoading,
  openModalWithChecksum,
}: ReleaseResultsProps) => {
  const t = useTranslations("Temurin.Releases.ReleaseResults");
  const tPage = useTranslations("TemurinReleases");
  const tFilters = useTranslations("Temurin.Releases.ReleaseFilters");
  const locale = useLocale();
  const [selectedArchitectures, setSelectedArchitectures] = useState<
    Record<string, string>
  >({});
  const [selectedPackageTypes, setSelectedPackageTypes] = useState<
    Record<string, string>
  >({});
  const [dismissedWarnings, setDismissedWarnings] = useState<
    Record<string, boolean>
  >({});
  const allChecksums = useMemo(
    () =>
      releases.flatMap((view) =>
        [
          view.binary?.package?.checksum,
          view.binary?.installer?.checksum,
        ].filter((checksum): checksum is string => Boolean(checksum)),
      ),
    [releases],
  );
  const { attestations, isLoading: attestationsLoading } = useAttestations(
    releases[0]?.release_name,
    allChecksums,
  );
  const hasAttestation = (checksum?: string | null) =>
    !attestationsLoading &&
    Boolean(checksum && attestations[checksum.toUpperCase()]);

  if (isLoading) {
    return (
      <section
        className="py-4"
        aria-label={tPage("loading")}
        aria-busy="true"
        data-testid="release-results-loading"
      >
        <div className="grid gap-4 lg:grid-cols-2">
          {[1, 2, 3].map((index) => (
            <div
              key={index}
              data-testid={`loading-skeleton-${index}`}
              className="rounded-2xl border border-white/10 bg-white/[0.025] p-6 motion-safe:animate-pulse"
            >
              <div className="mb-6 h-8 w-32 rounded bg-white/10" />
              <div className="mb-5 h-10 w-full rounded-xl bg-white/5" />
              <div className="h-12 w-full rounded-xl bg-white/5" />
            </div>
          ))}
        </div>
      </section>
    );
  }
  if (releases.length === 0) {
    return (
      <section className="py-8" data-testid="release-results-empty">
        <div className="rounded-2xl border border-white/10 bg-white/[0.025] px-6 py-12 text-center">
          <IoWarningOutline
            size={32}
            className="mx-auto mb-4 text-grey"
            data-testid="empty-state-icon"
            aria-hidden="true"
          />
          <h3
            className="mb-3 text-xl font-semibold text-white"
            data-testid="empty-state-title"
          >
            {t("no-releases-found")}
          </h3>
          <p
            className="mx-auto mb-0 max-w-md text-sm leading-relaxed text-grey"
            data-testid="empty-state-description"
          >
            {t("no-releases-found-description")}
          </p>
        </div>
      </section>
    );
  }

  const groupedReleases = releases.reduce<
    Record<string, Record<string, BinaryAssetView[]>>
  >((groups, view) => {
    const os = view.binary?.os ?? "unknown";
    const arch = view.binary?.architecture ?? "unknown";
    groups[os] ??= {};
    groups[os][arch] ??= [];
    groups[os][arch].push(view);
    return groups;
  }, {});
  const sortedOSEntries = Object.entries(groupedReleases).sort(([a], [b]) => {
    const rank = (os: string) =>
      osOrder.includes(os) ? osOrder.indexOf(os) : osOrder.length;
    return rank(a) - rank(b);
  });

  return (
    <section className="py-4" data-testid="release-results-content">
      <div className="grid items-start gap-4 lg:grid-cols-2">
        {sortedOSEntries.map(([os, architectures]) => {
          const Icon = osIcons[os] ?? FcLinux;
          const architectureList = Object.keys(architectures).sort((a, b) =>
            b.localeCompare(a),
          );
          const preferredArch =
            os === "mac" && architectureList.includes("aarch64")
              ? "aarch64"
              : architectureList.includes("x64")
                ? "x64"
                : architectureList[0];
          const selectedArch = architectures[selectedArchitectures[os]]
            ? selectedArchitectures[os]
            : preferredArch;
          const views = architectures[selectedArch];
          const types = [
            ...new Set(
              views
                .map((view) => view.binary?.image_type?.toLowerCase())
                .filter(Boolean),
            ),
          ];
          const storedType = selectedPackageTypes[`${os}-${selectedArch}`];
          const selectedType = types.includes(storedType)
            ? storedType
            : types.includes("jdk")
              ? "jdk"
              : types[0];
          const selectedViews = views.filter(
            (view) => view.binary?.image_type?.toLowerCase() === selectedType,
          );
          const firstView = views[0];
          const date = firstView?.binary?.updated_at;
          const warning =
            isUnsupportedPlatform(os, selectedArch) &&
            !dismissedWarnings[`${os}-${selectedArch}`];
          return (
            <div
              key={os}
              className="min-w-0 rounded-2xl border border-white/10 bg-white/[0.025] p-5 sm:p-6"
              data-testid={`release-card-${os}`}
            >
              <div className="mb-4 flex flex-wrap items-center justify-between gap-4">
                <div className="flex items-center gap-3">
                  <span
                    className="flex h-10 w-10 items-center justify-center rounded-xl bg-white/5"
                    aria-hidden="true"
                  >
                    <Icon size={24} />
                  </span>
                  <h3
                    className="mb-0 text-xl font-semibold"
                    data-testid={`os-title-${os}`}
                  >
                    {os === "mac"
                      ? "macOS"
                      : os.charAt(0).toUpperCase() + os.slice(1)}
                  </h3>
                </div>
                <div
                  role="group"
                  aria-label={tFilters("architecture")}
                  className="flex flex-wrap gap-1"
                  data-testid={`architecture-tabs-${os}`}
                >
                  {architectureList.map((arch) => (
                    <button
                      key={arch}
                      type="button"
                      aria-pressed={selectedArch === arch}
                      onClick={() =>
                        setSelectedArchitectures((prev) => ({
                          ...prev,
                          [os]: arch,
                        }))
                      }
                      data-testid={`arch-tab-${os}-${arch}`}
                      className={`min-h-10 rounded-lg border px-3 py-2 font-mono text-xs transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink ${selectedArch === arch ? "border-pink/30 bg-pink/10 text-[#ff91b7]" : "border-transparent text-grey hover:bg-white/5 hover:text-white"}`}
                    >
                      {os === "mac"
                        ? arch === "aarch64"
                          ? "Apple Silicon"
                          : arch === "x64"
                            ? "Intel"
                            : arch
                        : arch}
                    </button>
                  ))}
                </div>
              </div>

              {warning ? (
                <div
                  role="alert"
                  className="rounded-xl border border-amber-400/20 bg-amber-400/5 p-5 text-sm"
                  data-testid={`unsupported-warning-${os}-${selectedArch}`}
                >
                  <div className="mb-2 flex items-center gap-2 text-amber-300">
                    <IoWarningOutline size={22} aria-hidden="true" />
                    <h4 className="mb-0 font-semibold">
                      {t("unsupported-platform")}
                    </h4>
                  </div>
                  <p className="mb-3 leading-relaxed text-grey">
                    {t("unsupported-platform-description")}
                  </p>
                  <Link
                    href="/news/2025/12/solaris-win32-removal"
                    className="mb-4 inline-block text-[#ff91b7] underline"
                  >
                    {t("unsupported-platform-learn-more")}
                  </Link>
                  <button
                    type="button"
                    onClick={() =>
                      setDismissedWarnings((prev) => ({
                        ...prev,
                        [`${os}-${selectedArch}`]: true,
                      }))
                    }
                    className="block min-h-11 rounded-xl border border-white/20 px-4 py-2 text-grey hover:text-white focus-visible:outline-2 focus-visible:outline-pink"
                    data-testid={`show-downloads-${os}-${selectedArch}`}
                  >
                    {t("unsupported-platform-show-downloads")}
                  </button>
                </div>
              ) : (
                <>
                  <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
                    <div
                      role="group"
                      aria-label={tFilters("package-type")}
                      className="flex gap-1"
                      data-testid={`package-type-buttons-${os}-${selectedArch}`}
                    >
                      {["jdk", "jre"].map((type) => (
                        <button
                          key={type}
                          type="button"
                          disabled={!types.includes(type)}
                          aria-pressed={selectedType === type}
                          onClick={() =>
                            setSelectedPackageTypes((prev) => ({
                              ...prev,
                              [`${os}-${selectedArch}`]: type,
                            }))
                          }
                          data-testid={`${type}-button-${os}-${selectedArch}`}
                          className={`min-h-10 rounded-lg border px-3 py-2 text-xs font-medium transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink disabled:cursor-not-allowed disabled:opacity-30 ${selectedType === type ? "border-white/20 bg-white/10 text-white" : "border-transparent text-grey hover:bg-white/5"}`}
                        >
                          {type.toUpperCase()}
                        </button>
                      ))}
                    </div>
                    <p
                      className="mb-0 text-xs leading-relaxed text-grey"
                      data-testid={`release-header-${os}`}
                    >{`Temurin ${firstView?.release_name ?? ""}${date ? ` · ${new Date(date).toLocaleDateString(locale, { day: "2-digit", month: "2-digit", year: "numeric" })}` : ""}`}</p>
                  </div>
                  {selectedViews.some(
                    (view) =>
                      view.binary?.package?.link ||
                      view.binary?.installer?.link,
                  ) ? (
                    selectedViews.map((view, index) => {
                      const rowId = `${os}-${selectedArch}-${(view.binary?.image_type ?? "").toUpperCase()}-${index}`;
                      return (
                        <Fragment key={rowId}>
                          {view.binary?.package?.link && (
                            <DownloadRow
                              view={view}
                              artifact={view.binary.package}
                              os={os}
                              arch={selectedArch}
                              rowId={rowId}
                              reproduced={hasAttestation(
                                view.binary.package.checksum,
                              )}
                              openModalWithChecksum={openModalWithChecksum}
                            />
                          )}
                          {view.binary?.installer?.link && (
                            <DownloadRow
                              view={view}
                              artifact={view.binary.installer}
                              os={os}
                              arch={selectedArch}
                              rowId={`${rowId}-installer`}
                              installer
                              reproduced={hasAttestation(
                                view.binary.installer.checksum,
                              )}
                              openModalWithChecksum={openModalWithChecksum}
                            />
                          )}
                        </Fragment>
                      );
                    })
                  ) : (
                    <p className="mb-0 border-t border-white/10 pt-4 text-sm text-grey">
                      {tPage("no-downloads")}
                    </p>
                  )}
                </>
              )}
            </div>
          );
        })}
      </div>
    </section>
  );
};

export default ReleaseResults;
